INSERT INTO FO_ARJ_STEPS_PARAMS_BASE (ID,CHIAVE,DESCRIZIONE,FK_FO_ARJ_STEP_BASE) VALUES (36,'DISABILITA_RICERCA_SOGGETTI','Disabilita la ricerca delle anagrafiche. Inserire il valore 1.','ANAGRAFE');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCAREA', 'TIPOFORNITORE', 'Indicare in questo parametro il nome del fornitore di protocollo, questo dato è un enumeratore e serve, in base a quanto indicato, a gestire la parte variabile relativa all''APPLICATIVOPROTOCOLLO in quanto ogni protocollo lo gestisce a modo suo. Al momento è possibile inserire i seguenti dati: ADS, DATAGRAPH, DATAMANAGEMENT, NON_DEFINITO (default). Se non specificato sarà valorizzato in automatico il valore NON_DEFINITO.');
